// View tracking part 2: build ONE log row per call (no payloads ever reach here).
// Callers send small mapped fields only; if several items arrive they carry the same values.
const i = $input.first().json;
function str(v, max) { if (v === undefined || v === null || v === '') return null; return String(v).slice(0, max || 500); }
function num(v) { if (v === undefined || v === null || v === '' || isNaN(Number(v))) return null; return Math.round(Number(v)); }
function obj(v) { if (v && typeof v === 'object') return v; if (typeof v === 'string') { try { const p = JSON.parse(v); return (p && typeof p === 'object') ? p : null; } catch (e) { return null; } } return null; }
function decodeUser(u, auth) {
  if (!u) return null;
  if (auth !== 'in') return str(u, 200);
  try { return str(decodeURIComponent(u), 200); } catch (e) { return str(u, 200); }
}
const endpoint = str(i.endpoint, 100) || 'unknown';
const count = num(i.result_count);
const kind = (endpoint === 'v3/lookup' || endpoint === 'v3/manufacturer') ? 'lookup' : 'search';
let status = str(i.status_hint, 20);
if (!status) status = (count || 0) > 0 ? 'ok' : (kind === 'lookup' ? 'not-found' : 'empty');
let top = obj(i.top_results);
top = Array.isArray(top) ? top.slice(0, 5) : null;
const asked = str(i.asked_slug || i.slug, 300);
const returned = (top && top[0] && top[0].slug) ? String(top[0].slug) : null;
let matched_by = null;
if (endpoint === 'v3/lookup' && status === 'ok') {
  if (str(i.variant_slug, 300)) matched_by = 'variant';
  else if (returned && asked && returned !== asked) matched_by = 'source_slug';
  else matched_by = 'direct';
}
let filters = obj(i.filters);
if (filters && Array.isArray(filters)) filters = null;
return [{ json: { row: {
  endpoint: endpoint,
  method: str(i.method, 10),
  q: str(i.q, 200),
  slug: str(i.slug, 300),
  filters: filters,
  status: status,
  error: str(i.error, 200),
  found: status === 'ok',
  result_count: count,
  top_results: top,
  matched_by: matched_by,
  duration_ms: num(i.duration_ms),
  reason: str(i.reason, 200),
  source: str(i.source, 200),
  auth: str(i.auth, 200),
  user_name: decodeUser(i.user, i.auth),
  view_id: str(i.view, 200),
  prefetch: str(i.prefetch, 200),
  bot: str(i.bot, 200)
} } }];
